Found = False
Result = NONE
while (Pile1 has cards AND NOT Found) {
    Read a card X
    Move X to Pile2
    if (X matches the condition) {
        Found = True
        Result = X.CardNo
    }
}
Report Found and Result

Sentence = 1
Found = False
Result = NONE
while (cards remain AND NOT Found AND Sentence <= 3) {
    Read next word X in SerialNumber order
    Move X to the visited pile
    if (Sentence == 3 AND X.PartOfSpeech == "Verb") {
        Found = True
        Result = X.SerialNumber
    }
    if (X.Word ends in a full stop) {
        Sentence = Sentence + 1
    }
}

If the dataset is empty: report "No maximum"
Otherwise initialize Max from the first actual value
For every remaining value v {
    if (v > Max) {
        Max = v
    }
}
Report Max

If the dataset is empty: report "No minimum"
Otherwise initialize Min from its first actual value
For each remaining value v {
    if (v < Min) { Min = v }
}

Count = 0
Longest = 0
For each word X in paragraph order {
    Count = Count + 1
    if (X.Word ends in a full stop) {
        if (Count > Longest) { Longest = Count }
        Count = 0
    }
}
If Count > 0: handle the unfinished last segment by the stated rule

Counts = empty table
MaxCount = 0
For each record X {
    key = X.category
    If key has no counter: Counts[key] = 0
    Counts[key] = Counts[key] + 1
    if (Counts[key] > MaxCount) {
        MaxCount = Counts[key]
    }
}

Totals = empty table
MaxRevenue = 0
For each bill X {
    store = X.Store
    If store has no total: Totals[store] = 0
    Totals[store] = Totals[store] + X.BillAmount
    if (Totals[store] > MaxRevenue) {
        MaxRevenue = Totals[store]
    }
}

Frequency = empty table
MaxFrequency = 0
For each word card X {
    w = Normalize(X.Word)
    If w has no counter: Frequency[w] = 0
    Frequency[w] = Frequency[w] + 1
    if (Frequency[w] > MaxFrequency) {
        MaxFrequency = Frequency[w]
    }
}

If input is empty: report "No maximum"
Read first record X
Max = X.Mathematics
Owners = [X.CardNo]
For each remaining record X {
    if (X.Mathematics > Max) {
        Max = X.Mathematics
        Owners = [X.CardNo]
    }
    else if (X.Mathematics == Max) {
        Append X.CardNo to Owners
    }
}

Pass 1:
    Build Frequency for every normalized word
Pass 2:
    For every original word card X {
        w = Normalize(X.Word)
        if (Frequency[w] == 1) { keep X }
        else { discard X }
    }

FSum = 0
while (Pile1 has cards) {
    Read top card X
    Move X to Pile2
    if (X.Gender == "F") {
        FSum = FSum + X.Mathematics
    }
}

if (X.CityTown == "Chennai") {
    if (X.Gender == "F") { Count = Count + 1 }
}

